import 'bootstrap/dist/css/bootstrap.min.css';
import Button from 'react-bootstrap/Button';
import { Nav, Navbar, NavDropdown } from "react-bootstrap";
import Logo from "../../Images/Components/Navbar/four.png";
import "./Navbar.css";




function Navbar1(){
 return(
    <Navbar collapseOnSelect expand="lg" bg="" variant="dark">
      <Navbar.Brand>
        <font id='heading1'><img src={Logo} className='church-logo'/>Foursquare</font>
      </Navbar.Brand>
        <Nav className="d-flex justify-content-center "> 
          <Nav.Link href="#" style={{color:'black'}}>HOME</Nav.Link>
          <Nav.Link href="#" style={{color:'black'}}>ABOUT</Nav.Link>
          <Nav.Link href="#" style={{color:'black'}}> SERVE</Nav.Link>
          <Nav.Link href="#" style={{color:'black'}}>MEDIA</Nav.Link>
          <Nav.Link href="#" style={{color:'black'}}>CONTANT US</Nav.Link>
        </Nav>
      </Navbar>
);
}
export default Navbar1;
